define(['jquery','uiRegistry','Magento_Checkout/js/model/quote','Magento_Checkout/js/checkout-data'],function($,registry,quote,checkoutData){'use strict';var ALGER_REGION_ID='874',DEFAULT_COUNTRY='DZ',initialized=false;function setCountryDZ(countryComponent){if(countryComponent&&countryComponent.value()!==DEFAULT_COUNTRY){countryComponent.value(DEFAULT_COUNTRY);}}
function setDefaultRegion(regionComponent){return;}
function forceRegionVisible(regionComponent){if(regionComponent){regionComponent.visible(true);}}
function hideField(fieldName){registry.get('checkout.steps.shipping-step.shippingAddress.shipping-address-fieldset.'+fieldName,function(component){if(component&&typeof component.visible==='function'){component.visible(false);}});}
function initDefaults(){if(initialized){return;}
initialized=true;var shippingPrefix='checkout.steps.shipping-step.shippingAddress.shipping-address-fieldset.';registry.get(shippingPrefix+'country_id',function(countryComponent){setCountryDZ(countryComponent);registry.get(shippingPrefix+'region_id',function(regionComponent){forceRegionVisible(regionComponent);});});hideField('fax');hideField('postcode');hideField('company');hideField('middlename');if(checkoutData.setShippingAddressFromData){var addr=checkoutData.getShippingAddressFromData();if(addr&&!addr.country_id){addr.country_id=DEFAULT_COUNTRY;checkoutData.setShippingAddressFromData(addr);}}}
return function(){registry.async('checkout.steps.shipping-step.shippingAddress.shipping-address-fieldset.country_id')(function(){initDefaults();});$(document).ready(function(){setTimeout(function(){if(!initialized){initDefaults();}},2000);});};});